def log_diamond(path_a, path_b) do
  from = List.last(path_a) |> Map.fetch!(:component_path)
  to = List.first(path_a) |> Map.fetch!(:component_path)

  Membrane.Logger.debug(
    "Two paths from element #{from} to #{to} were detected, in which all pads are operating in pull mode. With such a pipeline configuration, the membrane flow control mechanism may stop demanding buffers. If you are debugging such an issue, keep in mind that input pads with `flow_control: :auto` demand data when there is a demand for data on ALL output pads with `flow_control: :auto`.

The first path from #{from} to #{to} leads:
#{inspect_path(path_a)}

The second path from #{from} to #{to} leads:
#{inspect_path(path_b)}
"
  )

  :ok
end

def buffers_size(:buffers, buffers) do
  {:ok, length(buffers)}
end
def buffers_size(:bytes, buffers) do
  size = Enum.reduce(buffers, 0, fn %Buffer{payload: p}, acc -> acc + Payload.size(p) end)
  {:ok, size}
end
def buffers_size(unit, _buffers) when is_timestamp_unit(unit) do
  {:error, :operation_not_supported}
end

def update_contexts(states, update_fun) do
  states
  |> Enum.map(fn {name, module, context, state} ->
    {name, module, update_fun.(context), state}
  end)
end

def def_options(module, options, child) do
  {opt_typespecs, escaped_opts} = parse_opts(options)
  typedoc = generate_opts_doc(escaped_opts)

  quote do
    @typedoc "Struct containing options for `#{inspect(__MODULE__)}`
"
    @type t :: %unquote(module){unquote_splicing(opt_typespecs)}
    @membrane_options_moduledoc "## #{unquote(child) |> to_string |> String.capitalize()} options

Passed via struct `t:#{inspect(__MODULE__)}.t/0`

#{unquote(typedoc)}
"
    @doc "Returns description of options available for this module\n"
    @spec options() :: keyword
    def options() do
      unquote(escaped_opts)
    end

    @enforce_keys unquote(escaped_opts)
                  |> Enum.reject(fn {k, v} -> v |> Keyword.has_key?(:default) end)
                  |> Keyword.keys()
    defstruct unquote(escaped_opts) |> Enum.map(fn {k, v} -> {k, v[:default]} end)
  end
end

